using System.Numerics;
using SiJenggo.Game.Components;
using static SiJenggo.Game.Data.MoveFlags;

namespace SiJenggo.Game.Data;

/// <summary>
/// Every attack in the game, registered once at startup. Ids are assigned in declaration order,
/// which is stable across machines (needed for lockstep replays).
/// </summary>
public static class Moves
{
    private static readonly List<MoveDef> s_all = [null!];

    private static MoveId R(MoveDef def)
    {
        def.Id = new MoveId((ushort)s_all.Count);
        s_all.Add(def);
        return def.Id;
    }

    public static MoveDef Get(MoveId id) => s_all[id.Value];
    public static IReadOnlyList<MoveDef> All => s_all;
    public static int Count => s_all.Count - 1;

